JOB_REQ = {
    "title": "Software Engineer",
    "family": "Software Engineering",
    "title_terms": ["software", "engineer", "backend", "frontend", "developer", "data", "cloud", "devops"],
    "req_skills": ["python", "aws", "react", "java", "sql", "docker", "javascript", "kubernetes"],
    "min_experience": 5,
    "education": "BS"
}


async def run_validation():
    print(f"\n{'='*60}")
    print(f"PHASE 7: 200-RESUME VALIDATION")
    print(f"Parser: AIPipeline.parse_resume (ontology-based)")
    print(f"{'='*60}\n")
    
    ts_start = time.time()
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    
    # ── Parse all 200 resumes ──────────────────────────────────────────────
    parse_start = time.time()
    parsed_all = []
    for r in RESUMES:
        parsed = await AIPipeline.parse_resume(r["text"])
        parsed_all.append(parsed)
    parse_end = time.time()
    parser_runtime_ms = (parse_end - parse_start) * 1000
    
    # ── Per-resume metrics ─────────────────────────────────────────────────
    all_fps = []
    all_fns = []
    precisions = []
    recalls = []
    title_matches = 0
    yoe_errors = []
    
    extraction_rows = []
    
    for i, (r, parsed) in enumerate(zip(RESUMES, parsed_all)):
        gt = r["gt"]
        cid = r["id"]
        
        ext_title = parsed.get("current_title", "")
        ext_yoe = parsed.get("total_years_of_experience", 0)
        ext_skills = [s["name"] for s in parsed.get("skills", [])]
        ext_edu = len(parsed.get("education", []))
        ext_cert = len(parsed.get("certifications", []))
        
        gt_s = set(s.lower() for s in gt["skills"])
        ext_s = set(s.lower() for s in ext_skills)
        tp = gt_s & ext_s
        fp = ext_s - gt_s
        fn = gt_s - ext_s
        
        prec = len(tp) / len(ext_s) if ext_s else 0.0
        rec = len(tp) / len(gt_s) if gt_s else 1.0
        
        all_fps.extend(fp)
        all_fns.extend(fn)
        precisions.append(prec)
        recalls.append(rec)
        
        title_match = gt["title"].lower() in ext_title.lower() or ext_title.lower() in gt["title"].lower()
        if title_match: title_matches += 1
        
        yoe_err = abs(ext_yoe - gt["yoe"])
        yoe_errors.append(yoe_err)
        
        extraction_rows.append({
            "id": cid,
            "extracted_title": ext_title,
            "gt_title": gt["title"],
            "title_match": "YES" if title_match else "NO",
            "extracted_yoe": ext_yoe,
            "gt_yoe": gt["yoe"],
            "yoe_error": yoe_err,
            "extracted_skill_count": len(ext_s),
            "gt_skill_count": len(gt_s),
            "precision": round(prec, 3),
            "recall": round(rec, 3),
            "education_count": ext_edu,
            "certification_count": ext_cert,
        })

    # ── Ranking test ───────────────────────────────────────────────────────
    gt_cands = []
    pa_cands = []
    for i, (r, parsed) in enumerate(zip(RESUMES, parsed_all)):
        gt = r["gt"]
        yoe = gt["yoe"]
        sy = 2026 - yoe
        gt_mapped = {
            "current_title": gt["title"],
            "total_years_of_experience": yoe,
            "skills": [{"name": s, "type": "hard"} for s in gt["skills"]],
            "education": [{"degree": "BS", "institution": "University"}],
            "certifications": [],
            "experiences": [{"title": gt["title"], "company": "Company", "start_date": f"Jan {sy}", "end_date": "Present", "duration_months": yoe * 12, "bullets": ["Work"]}],
        }
        pa_mapped = {
            "current_title": parsed.get("normalized_title", parsed.get("current_title", "")),
            "total_years_of_experience": parsed.get("total_years_of_experience", 0),
            "skills": parsed.get("skills", []),
            "education": parsed.get("education", []),
            "certifications": parsed.get("certifications", []),
            "experiences": [
                {
                    "title": parsed.get("normalized_title", exp.get("title", "")) if idx == 0 else exp.get("title", ""),
                    "company": exp.get("company", ""),
                    "start_date": exp.get("start_date", ""),
                    "end_date": exp.get("end_date", ""),
                    "duration_months": exp.get("duration_months", 0),
                    "bullets": ["Work"]
                }
                for idx, exp in enumerate(parsed.get("experiences", []))
            ]
        }
        gt_cands.append({"id": f"gt_{i}", "parsed_data": gt_mapped})
        pa_cands.append({"id": f"pa_{i}", "parsed_data": pa_mapped})

    rank_start = time.time()
    ranked_gt = await rank_candidates_for_job("validation200", JOB_REQ, gt_cands)
    ranked_pa = await rank_candidates_for_job("validation200", JOB_REQ, pa_cands)
    rank_end = time.time()
    ranking_runtime_ms = (rank_end - rank_start) * 1000
    
    gt_ranks = {r["id"]: r["rank"] for r in ranked_gt["results"]}
    pa_ranks = {r["id"]: r["rank"] for r in ranked_pa["results"]}
    
    shifts = []
    for i in range(len(RESUMES)):
        gt_r = gt_ranks.get(f"gt_{i}", len(RESUMES))
        pa_r = pa_ranks.get(f"pa_{i}", len(RESUMES))
        shifts.append(abs(gt_r - pa_r))
    
    shifts_sorted = sorted(shifts)
    mean_shift = sum(shifts) / len(shifts)
    median_shift = shifts_sorted[len(shifts_sorted) // 2]
    p95_shift = shifts_sorted[int(len(shifts_sorted) * 0.95)]
    max_shift = max(shifts)
    
    # ── Aggregate metrics ──────────────────────────────────────────────────
    mean_precision = sum(precisions) / len(precisions)
    mean_recall = sum(recalls) / len(recalls)
    title_accuracy = title_matches / len(RESUMES)
    mean_yoe_error = sum(yoe_errors) / len(yoe_errors)
    
    fp_counts = Counter(all_fps)
    fn_counts = Counter(all_fns)
    
    # ── Output ─────────────────────────────────────────────────────────────
    total_runtime_ms = (time.time() - ts_start) * 1000
    
    lines = []
    lines.append("# PHASE 7 — 200-RESUME VALIDATION REPORT\n")
    lines.append(f"**Execution Timestamp**: {timestamp}  ")
    lines.append(f"**Parser Runtime (200 docs)**: {parser_runtime_ms:.1f} ms  ")
    lines.append(f"**Ranking Runtime (400 candidates)**: {ranking_runtime_ms:.1f} ms  ")
    lines.append(f"**Total Runtime**: {total_runtime_ms:.1f} ms  ")
    lines.append("")
    lines.append("## COMPUTED METRICS")
    lines.append(f"- Skill Precision: {mean_precision*100:.2f}%")
    lines.append(f"- Skill Recall: {mean_recall*100:.2f}%")
    lines.append(f"- Title Accuracy: {title_accuracy*100:.2f}%")
    lines.append(f"- YOE Mean Error: {mean_yoe_error:.2f} years")
    lines.append("")
    lines.append("## RANK SHIFTS")
    lines.append(f"- Mean: {mean_shift:.2f}")
    lines.append(f"- Median: {median_shift:.2f}")
    lines.append(f"- P95: {p95_shift}")
    lines.append(f"- Max: {max_shift}")
    lines.append("")
    lines.append("## TARGET VS ACTUAL")
    lines.append(f"| Metric | Target | Actual | Pass? |")
    lines.append(f"|--------|--------|--------|-------|")
    lines.append(f"| Skill Precision | >=95% | {mean_precision*100:.1f}% | {'PASS' if mean_precision >= 0.95 else 'FAIL'} |")
    lines.append(f"| Skill Recall | >=95% | {mean_recall*100:.1f}% | {'PASS' if mean_recall >= 0.95 else 'FAIL'} |")
    lines.append(f"| Title Accuracy | >=95% | {title_accuracy*100:.1f}% | {'PASS' if title_accuracy >= 0.95 else 'FAIL'} |")
    lines.append(f"| YOE Error | <=0.5yr | {mean_yoe_error:.2f}yr | {'PASS' if mean_yoe_error <= 0.5 else 'FAIL'} |")
    lines.append(f"| Mean Rank Shift | <=2 | {mean_shift:.2f} | {'PASS' if mean_shift <= 2 else 'FAIL'} |")
    lines.append(f"| Median Rank Shift | <=1 | {median_shift:.2f} | {'PASS' if median_shift <= 1 else 'FAIL'} |")
    lines.append(f"| P95 Rank Shift | <=5 | {p95_shift} | {'PASS' if p95_shift <= 5 else 'FAIL'} |")
    lines.append("")
    lines.append("## PER-RESUME EXTRACTION (ALL 200)")
    lines.append("| ID | Extracted Title | GT Title | Title Match | Ext YOE | GT YOE | YOE Err | Skills Ext | Skills GT | Precision | Recall | Edu | Cert |")
    lines.append("|----|----|----|----|----|----|----|----|----|----|----|----|-----|")
    for row in extraction_rows:
        lines.append(f"| {row['id']} | {row['extracted_title'][:30]} | {row['gt_title'][:25]} | {row['title_match']} | {row['extracted_yoe']} | {row['gt_yoe']} | {row['yoe_error']} | {row['extracted_skill_count']} | {row['gt_skill_count']} | {row['precision']:.2f} | {row['recall']:.2f} | {row['education_count']} | {row['certification_count']} |")
    
    lines.append("")
    lines.append("## TOP 25 FALSE NEGATIVES (missed skills)")
    for k, v in fn_counts.most_common(25):
        lines.append(f"- {k} ({v})")
    
    lines.append("")
    lines.append("## TOP 25 FALSE POSITIVES (extra skills)")
    for k, v in fp_counts.most_common(25):
        lines.append(f"- {k} ({v})")
    
    lines.append("")
    lines.append("## RESUME SOURCE LIST")
    lines.append("Source: 200 Manually Curated Resumes — Multi-industry (Software, Data, Cloud, Security, Networking, Mobile, Embedded, Automotive, Manufacturing, Energy, Finance, Healthcare, Sales, Marketing)")
    lines.append("Format: Plain text resume layouts (not generated by reportlab, not synthetic benchmark)")
    
    report = "\n".join(lines)
    with open("validation_200_report.md", "w", encoding="utf-8") as f:
        f.write(report)
    
    # Print summary
    print(report)
    print(f"\n[DONE] Report saved to validation_200_report.md")


if __name__ == "__main__":
    asyncio.run(run_validation())
